<?php
defined('ABSPATH')||exit;final class SPL_SEO{public function hooks(){add_action('wp_head',array($this,'schema'),40);add_filter('wp_robots',array($this,'robots'));}public function schema(){if(!is_singular(SPL_Helpers::TYPE))return;$id=get_queried_object_id();$type='book'===sanitize_title(SPL_Helpers::term($id,SPL_Helpers::DOCTYPE))?'Book':'DigitalDocument';$d=array('@context'=>'https://schema.org','@type'=>$type,'name'=>get_the_title($id),'author'=>array('@type'=>'Person','name'=>SPL_Helpers::meta($id,'author_name')),'description'=>get_the_excerpt($id),'inLanguage'=>SPL_Helpers::meta($id,'language'),'datePublished'=>SPL_Helpers::meta($id,'publication_year'),'isbn'=>SPL_Helpers::meta($id,'isbn'),'image'=>get_the_post_thumbnail_url($id,'full'));echo'<script type="application/ld+json">'.wp_json_encode($d,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE).'</script>';}public function robots($r){$m=(array)get_option('spl_page_map',array());foreach(array('saved','reading')as$k)if(!empty($m[$k])&&is_page($m[$k])){$r['noindex']=true;$r['noarchive']=true;}return$r;}}

